#include <utility>

struct Parcel {};
void Handle(Parcel&) {}
void Handle(Parcel&&) {}

template <typename T>
void Relay(T&& value) {
  Handle(std::forward<T>(value));
}

int main() {
  Parcel parcel;
  Relay(parcel);
}
// Здесь T — Parcel&, параметр после схлопывания — Parcel&.
// forward сохраняет доступ как lvalue: выбирается Handle(Parcel&).
// При Relay(Parcel{}) имя value в Handle(value) тоже было бы lvalue.
